#include <omp.h>
#include <vector>
#include <array>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize output bins to zero
    bins.fill(0);

    // Empty input: nothing to count
    if (x.empty()) return;

    // Get maximum possible threads to allocate per‑thread local counters
    int maxThreads = omp_get_max_threads();
    std::vector<std::array<size_t, 10>> localCounts(maxThreads);
    for (int t = 0; t < maxThreads; ++t) {
        localCounts[t].fill(0);
    }

    // Parallel loop: each thread updates its own local counter array
    #pragma omp parallel for
    for (size_t i = 0; i < x.size(); ++i) {
        int tid = omp_get_thread_num();
        double val = x[i];
        size_t bin = static_cast<size_t>(val / 10.0);
        // Clamp values >= 100 to the last bin
        if (bin >= 10) bin = 9;
        ++localCounts[tid][bin];
    }

    // Combine the per‑thread results into the output array
    for (int t = 0; t < maxThreads; ++t) {
        for (size_t b = 0; b < 10; ++b) {
            bins[b] += localCounts[t][b];
        }
    }
}
